import {test,before,after} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,mkdirSync,readFileSync,writeFileSync,rmSync,symlinkSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {gunzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {fixedLocalGit} from '../fixed-local-git.mjs';
import {collectVerificationRetirementCandidates,verifyVerificationRetirementCandidates} from '../implementation-verification-retirements.mjs';
import {collectVerificationRetirementEntryEvidence} from '../implementation-verification-inputs.mjs';
import {buildVerificationInputContext,buildVerificationConsumerGraphFacts,assertVerificationInputContext} from '../implementation-verification-context.mjs';
const root=fileURLToPath(new URL('../../../',import.meta.url));
const DATA=JSON.parse(gunzipSync(Buffer.from('','base64')));
const CATALOG='config/verification-retirements/closed-components-v1.json',BASE='69de823cda6d789130898399c3ad770c15b6fb71';
const canonical=x=>Array.isArray(x)?x.map(canonical):x&&typeof x==='object'?Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k])])):x;
const sha=x=>createHash('sha256').update(JSON.stringify(canonical(x))).digest('hex');
const seal=(body,key)=>({...body,[key]:sha(body)});
let home,sourceRoot,controlRoot,HEAD;
const git=(dir,...args)=>fixedLocalGit(dir,['-c','commit.gpgSign=false',...args],{encoding:'utf8',localClone:false}).trim();
const commit=dir=>{git(dir,'add','--sparse','.');git(dir,'-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit','--allow-empty','-qm','test: exact closed component source');return git(dir,'rev-parse','HEAD');};
const write=(path,text)=>{mkdirSync(dirname(join(sourceRoot,path)),{recursive:true});writeFileSync(join(sourceRoot,path),text);};
const current=()=>({repo:'perfectuser21/cecelia',base_revision:BASE,head_revision:git(sourceRoot,'rev-parse','HEAD'),changed_files:fixedLocalGit(sourceRoot,['diff','--no-renames','--name-only','-z',BASE,'HEAD','--'],{encoding:'utf8'}).split('\0').filter(Boolean).map(path=>({path}))});
const options=()=>({source:current(),toolingRoot:controlRoot,toolingRevision:git(controlRoot,'rev-parse','HEAD'),purpose:'admission_only'});
const proof=()=>collectVerificationRetirementCandidates(sourceRoot,options());
const reset=()=>{git(sourceRoot,'reset','--hard',HEAD);git(sourceRoot,'clean','-fd');};
before(()=>{
 home=mkdtempSync(join(tmpdir(),'closed-component-retirement-'));sourceRoot=join(home,'source');controlRoot=join(home,'control');
 fixedLocalGit(root,['clone','--shared','--no-checkout','--quiet',root,sourceRoot],{localClone:true});
 git(sourceRoot,'remote','set-url','origin','https://github.com/perfectuser21/cecelia.git');
 const selected=[CATALOG,...DATA.catalog.records.map(r=>r.path),...Object.keys(DATA.replacement_sources),...Object.keys(DATA.config_sources),...Object.keys(DATA.reference_sources),'.github/workflows/ci.yml','scripts/ci/check-basic-results.mjs','scripts/ci/ops-checks.mjs','packages/quality/package.json'];
 git(sourceRoot,'sparse-checkout','set','--no-cone',...selected.map(p=>'/'+p));git(sourceRoot,'checkout','--detach',BASE);
 for(const[path,text]of Object.entries({...DATA.config_sources,...DATA.replacement_sources,...DATA.reference_sources}))write(path,text);
 for(const row of DATA.catalog.records)git(sourceRoot,'update-index','--force-remove',row.path);
 for(const row of DATA.catalog.records)rmSync(join(sourceRoot,row.path),{force:true});
 write(CATALOG,DATA.catalog_text);HEAD=commit(sourceRoot);
 mkdirSync(controlRoot);git(controlRoot,'init','-q');git(controlRoot,'remote','add','origin','https://github.com/perfectuser21/cecelia.git');
 for(const name of ['alertness-v1.json','legacy-five-v1.json']){const p='config/verification-retirements/'+name;mkdirSync(dirname(join(controlRoot,p)),{recursive:true});writeFileSync(join(controlRoot,p),readFileSync(join(root,p)));}commit(controlRoot);
});
after(()=>{if(home)rmSync(home,{recursive:true,force:true});});

test('完整420闭包只形成405紧凑候选，15原生selected不额外授权',()=>{
 const p=proof();assert.equal(p.rows.length,405);assert.equal(p.closed_component_bundle.closure_records.length,420);
 assert.equal(p.closed_component_bundle.replacement_inputs.length,3);assert.equal(p.closed_component_bundle.reference_updates.length,13);assert.equal(p.rows.some(r=>r.replacement_inputs),false);
 const native=DATA.catalog.records.filter(r=>r.classification==='native_selected');assert.ok(native.every(r=>!p.rows.some(x=>x.path===r.path)));
 assert.equal(p.coverage,'unknown');assert.equal(p.execution_status,'not_evaluated');
 assert.deepEqual(verifyVerificationRetirementCandidates(sourceRoot,{...options(),proof:p}),p);
 assert.ok(Buffer.byteLength(JSON.stringify(p))<1000000);
});

function contextFixture({baseEdges=DATA.internal_edges,headEdges=[],scopes=['cecelia-kr','cecelia-factory','cecelia-infra'],owner=true}={}){
 const p=proof();assert.equal(p.rows.length,405);const source=current(),paths=[...DATA.catalog.records.map(r=>r.path),...Object.keys(DATA.reference_sources),CATALOG];
 const reports=[],facts=[];
 for(const key of scopes){const registryRepo=key+'-source',report={scope_key:key,registry_repo:registryRepo,source,ci_context:{purpose:'admission_only'},affected_usages:[],verification_owner_coverage:{}};
  const scope={scope_key:key,registry_repo:registryRepo};
  for(const side of ['base','head']){const edges=side==='base'?baseEdges:headEdges,revision=source[side+'_revision'];
   const raw=buildVerificationConsumerGraphFacts({source,side,registryRepo,graphSnapshot:{repo:registryRepo,source_revision:revision,row_count:edges.length},edges,paths});scope[side]=raw;
   report[side]={revision,mapping_status:'verified',traversal:{truncated:false},graph_snapshot:{source_revision:revision,digest:raw.graph_snapshot_digest,row_count:edges.length},file_coverage:source.changed_files.map(({path})=>({path,matched_paths:[],truncated:false}))};
   report.affected_usages.push({evidence:[{side,revision,implementation:{repo:source.repo,registry_repo:registryRepo,revision,path:'.github/workflows/ci.yml'}}]});
   report.verification_owner_coverage[side]=[{path:DATA.catalog.replacement_config.path,matched_paths:owner?['.github/workflows/ci.yml']:[],truncated:false,source_revision:revision,graph_sha256:raw.graph_snapshot_digest}];
  }reports.push(report);facts.push(scope);
 }
 const evidence=seal({schema_version:1,purpose:'admission_only',evidence_kind:'derived_verification_input_candidates',source,rows:[]},'verification_inputs_sha256');
 const entries=collectVerificationRetirementEntryEvidence(sourceRoot,{source,proof:p});
 return {source,evidence,reports,raw_consumer_graph_facts:{scopes:facts},retirement_candidates:p,retirement_entry_evidence:entries};
}
test('三scope真实闭包结构+head入口/owner共同授权405退役及唯一catalog数据，仍未知执行与覆盖',()=>{
 const f=contextFixture(),c=buildVerificationInputContext(f);assert.equal(c.authorized_retirements.length,405);
 assert.equal(c.joint_files.filter(r=>r.resolution_kind==='closed_component_retirement').length,405);
 assert.equal(c.joint_files.filter(r=>r.path===CATALOG&&r.non_executable).length,1);assert.equal(c.joint_files.filter(r=>r.resolution_kind==='reference_cleanup').length,13);
 assert.equal(c.execution_status,'not_evaluated');assert.equal(c.coverage,'unknown');assert.deepEqual(assertVerificationInputContext({source:f.source,reports:f.reports,context:c}),c);
 assert.ok(Buffer.byteLength(JSON.stringify(c))<8*1024*1024);
});
for(const [name,opts]of [
 ['base存活外部消费者',{baseEdges:[...DATA.internal_edges,{src_path:'packages/brain/src/still-active.js',dst_path:DATA.catalog.records[0].path,edge_type:'import',detail:{}}]}],
 ['head存活消费者',{headEdges:[{src_path:'packages/brain/src/still-active.js',dst_path:DATA.catalog.records[0].path,edge_type:'import',detail:{}}]}],
 ['缺任一scope',{scopes:['cecelia-kr','cecelia-factory']}],['无head owner',{owner:false}],
])test(`闭包不完整不得授权任何一项或catalog：${name}`,()=>{
 const c=buildVerificationInputContext(contextFixture(opts));assert.equal(c.authorized_retirements.length,0);assert.equal(c.joint_files.some(r=>r.path===CATALOG),false);
});
for(const kind of ['subset','modified','symlink','directory','rename'])test(`删除伪装整体拒绝：${kind}`,()=>{
 const path=DATA.catalog.records[1].path;
 try{
  if(kind==='subset')write(path,git(sourceRoot,'show',BASE+':'+path));
  if(kind==='modified')write(path,'export const changed=true;\n');
  if(kind==='symlink'){mkdirSync(dirname(join(sourceRoot,path)),{recursive:true});symlinkSync('/tmp/foreign',join(sourceRoot,path));}
  if(kind==='directory')write(path+'/nested.js','export const nested=true;\n');
  if(kind==='rename')write(path+'.renamed',git(sourceRoot,'show',BASE+':'+path));
  commit(sourceRoot);assert.throws(proof,/COMPONENT|DELETION|ABSENCE/);
 }finally{reset();}
});
for(const path of [CATALOG,...Object.keys(DATA.replacement_sources),DATA.catalog.replacement_config.path])test(`catalog或替代真实字节漂移拒绝：${path}`,()=>{
 try{write(path,readFileSync(join(sourceRoot,path),'utf8')+'\n');commit(sourceRoot);assert.throws(proof,/COMPONENT|CATALOG|REPLACEMENT|CONFIG/);}finally{reset();}
});
for(const path of Object.keys(DATA.reference_sources))test(`13项参考清理逐head精确字节核验：${path}`,()=>{
 try{write(path,readFileSync(join(sourceRoot,path),'utf8')+'\n# 未审参考更改\n');commit(sourceRoot);assert.throws(proof,/COMPONENT_REFERENCE/);}finally{reset();}
});
test('catalog symlink、用途漂移与自算witness不能获得退役资格',()=>{
 for(const purpose of ['main','release','recovery'])assert.throws(()=>collectVerificationRetirementCandidates(sourceRoot,{...options(),purpose}),/ADMISSION_ONLY/);
 const p=proof();p.closed_component_bundle.closure_records[0].classification='component_file';
 const {retirement_candidates_sha256,...body}=p;const forged=seal(body,'retirement_candidates_sha256');
 assert.throws(()=>verifyVerificationRetirementCandidates(sourceRoot,{...options(),proof:forged}),/WITNESS_MISMATCH/);
 try{rmSync(join(sourceRoot,CATALOG));symlinkSync('/tmp/foreign-catalog',join(sourceRoot,CATALOG));commit(sourceRoot);assert.throws(proof,/REGULAR|COMPONENT|CATALOG/);}finally{reset();}
});
test('旧base blob任一字节漂移，即使head仍完全删除也不能继承精确审查',()=>{
 const path=DATA.catalog.records[1].path;
 try{
  git(sourceRoot,'checkout','--detach',BASE);write(path,git(sourceRoot,'show',BASE+':'+path)+'\n// 未审旧字节\n');const altered=commit(sourceRoot);
  const candidate=git(sourceRoot,'-c','user.name=Fixture','-c','user.email=fixture@example.invalid','commit-tree',HEAD+'^{tree}','-p',altered,'-m','test: deletion cannot erase base drift');git(sourceRoot,'reset','--hard',candidate);
  const source={...current(),base_revision:altered,changed_files:git(sourceRoot,'diff','--no-renames','--name-only',altered,candidate).split('\n').map(path=>({path}))};
  assert.throws(()=>collectVerificationRetirementCandidates(sourceRoot,{...options(),source}),/COMPONENT_BASE_BLOB|COMPONENT_BASE_BYTES/);
 }finally{reset();}
});
test('三scope任一raw截断与替代入口缺失都不能授权',()=>{
 const f=contextFixture(),scope=f.raw_consumer_graph_facts.scopes[0],body={...scope.base};delete body.raw_graph_facts_sha256;body.rows[0].truncated=true;scope.base=seal(body,'raw_graph_facts_sha256');
 assert.throws(()=>buildVerificationInputContext(f),/RAW_GRAPH_INVALID/);
 const entry=contextFixture(),{retirement_entry_candidates_sha256,...entryBody}=entry.retirement_entry_evidence;
 entryBody.closed_component_replacement_entries[0].entry=null;entry.retirement_entry_evidence=seal(entryBody,'retirement_entry_candidates_sha256');
 const result=buildVerificationInputContext(entry);assert.equal(result.authorized_retirements.length,0);assert.equal(result.joint_files.some(r=>r.path===CATALOG),false);
});
test('未列路径没有目录豁免，catalog缺失也不给420删除授权',()=>{
 try{write('frontend/unreviewed-audit-data.json','{"unreviewed":true}');commit(sourceRoot);assert.equal(proof().rows.some(r=>r.path==='frontend/unreviewed-audit-data.json'),false);}finally{reset();}
 try{git(sourceRoot,'rm','--sparse',CATALOG);commit(sourceRoot);assert.equal(proof().rows.length,0);}finally{reset();}
});
